<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount,watch,nextTick} from 'vue'
import {layoutSkyline,pickPitch,prismAt,silhouette,pointsAttr,project,unproject} from './contribution-skyline/skyline.geometry'
import {sampleCells,DATASETS} from './contribution-skyline/skyline.sample'
import type {SkylinePrism} from './contribution-skyline/skyline.types'
import './contribution-skyline/skyline.css'
const dataset=ref('Synthetic year'),state=ref('ready'),mode=ref('grid'),drawMode=ref('grid')
const root=ref<HTMLElement|null>(null),board=ref<HTMLElement|null>(null),scene=ref<HTMLElement|null>(null),tooltip=ref<HTMLElement|null>(null),tableScroll=ref<HTMLElement|null>(null)
const pitch=ref(10),progress=ref(1),fade=ref(1),selectedDate=ref<string|null>(null),hoverDate=ref<string|null>(null),focused=ref(false),focusVisible=ref(false)
const tip=ref<{date:string;origin:'hover'|'focus'|'pinned'}|null>(null),pinnedBy=ref<'pointer'|'keyboard'|null>(null),suppressed=ref(false),suppressedDate=ref<string|null>(null),live=ref(''),tableOpen=ref(false),tableOverflow=ref(false),tipStyle=ref({left:'8px',top:'8px',visibility:'hidden' as 'hidden'|'visible'})
const dataT=ref(1),oldHeights=ref<Record<string,number|null>>({})
let raf=0,positionRaf=0,grace:ReturnType<typeof setTimeout>|undefined,overTip=false,observer:ResizeObserver|undefined,media:MediaQueryList|undefined,reduced=false,epoch=0
const cells=computed(()=>sampleCells(dataset.value)),days=computed(()=>cells.value.filter(c=>c.date!==null)),weeks=computed(()=>Math.ceil(cells.value.length/7))
const layout=computed(()=>layoutSkyline(cells.value,weeks.value,pitch.value)),selected=computed(()=>layout.value.prisms.find(p=>p.date===selectedDate.value))
const text=(date:string)=>{const d=days.value.find(c=>c.date===date);return `${date}: ${d?.count===null?'no data':d?.count+' contributions'} (synthetic)`}
const monthMarkers=computed(()=>days.value.filter((c,i,a)=>i===0||c.date!.slice(0,7)!==a[i-1].date!.slice(0,7)).map(c=>({col:c.col,label:['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][Number(c.date!.slice(5,7))-1]})))
function cancelGrace(){if(grace)clearTimeout(grace);grace=undefined}
function closeTip(suppress=false){cancelGrace();tip.value=null;pinnedBy.value=null;if(suppress){suppressed.value=true;suppressedDate.value=hoverDate.value??selectedDate.value}}
function clear(){closeTip();hoverDate.value=null;suppressed.value=false}
async function position(){await nextTick();if(!tip.value||!tooltip.value)return;const n=Array.from(root.value?.querySelectorAll<HTMLElement>('[data-date]')??[]).find(n=>n.dataset.date===tip.value!.date&&n.getBoundingClientRect().width>0);if(!n)return;const top=n.querySelector('.skyusage-top')??n,b=top.getBoundingClientRect(),t=tooltip.value.getBoundingClientRect();const y=b.top-t.height-8;tipStyle.value={left:Math.max(8,Math.min(innerWidth-t.width-8,b.left+b.width/2-t.width/2))+'px',top:Math.max(8,Math.min(innerHeight-t.height-8,y>=8?y:b.bottom+8))+'px',visibility:'visible'}}
function show(date:string,origin:'hover'|'focus'|'pinned',announce=false){tip.value={date,origin};if(announce)live.value=text(date);void position()}
function leave(){hoverDate.value=null;cancelGrace();grace=setTimeout(()=>{if(!overTip&&!hoverDate.value&&tip.value?.origin==='hover')closeTip()},120)}
function enter(date:string,e:PointerEvent){if(e.pointerType==='touch')return;cancelGrace();hoverDate.value=date;if(suppressed.value&&date!==suppressedDate.value)suppressed.value=false;if(!suppressed.value&&!pinnedBy.value&&tip.value?.origin!=='focus')show(date,'hover')}
function pin(date:string,by:'pointer'|'keyboard'){cancelGrace();suppressed.value=false;selectedDate.value=date;if(pinnedBy.value&&tip.value?.date===date){pinnedBy.value=null;if(by==='keyboard'&&focused.value)show(date,'focus',true);else closeTip();return}pinnedBy.value=by;show(date,'pinned',true)}
function focusScene(){focused.value=true;focusVisible.value=!!scene.value?.matches(':focus-visible');selectedDate.value??=days.value.at(-1)?.date??null;if(selectedDate.value&&!suppressed.value)show(selectedDate.value,'focus',true)}
function blurScene(){focused.value=false;focusVisible.value=false;if(tip.value?.origin==='focus'||pinnedBy.value==='keyboard')closeTip()}
function key(e:KeyboardEvent){if(e.key==='Escape'){closeTip(true);return}const index=days.value.findIndex(c=>c.date===selectedDate.value),last=days.value.length-1;const delta:Record<string,number>={ArrowLeft:-7,ArrowRight:7,ArrowUp:-1,ArrowDown:1,PageUp:-28,PageDown:28};if(e.key==='Enter'||e.key===' '){e.preventDefault();if(selectedDate.value)pin(selectedDate.value,'keyboard');return}if(!(e.key in delta)&&e.key!=='Home'&&e.key!=='End')return;e.preventDefault();const candidate=index+delta[e.key];const next=e.key==='Home'?0:e.key==='End'?last:candidate<0||candidate>last?index:candidate;selectedDate.value=days.value[next]?.date??null;suppressed.value=false;pinnedBy.value=null;if(selectedDate.value){show(selectedDate.value,'focus',true);if(drawMode.value==='grid')nextTick(()=>root.value?.querySelector<HTMLButtonElement>(`button[data-date="${selectedDate.value}"]`)?.focus())}}
function pointerOutside(e:PointerEvent){if(!board.value?.contains(e.target as Node)&&!tooltip.value?.contains(e.target as Node))closeTip()}
function escape(e:KeyboardEvent){if(e.key==='Escape'&&tip.value)closeTip(true)}
function moved(){if(tip.value?.origin==='hover')closeTip();else if(tip.value){cancelAnimationFrame(positionRaf);positionRaf=requestAnimationFrame(()=>void position())}}
function blankTap(e:MouseEvent){if((e.target as Element).closest('[data-date]'))return;const svg=e.currentTarget as SVGSVGElement,point=svg.createSVGPoint();point.x=e.clientX;point.y=e.clientY;const m=svg.getScreenCTM();if(!m)return;const local=point.matrixTransform(m.inverse()),cell=unproject(local.x,local.y,pitch.value,layout.value),d=days.value.find(d=>d.col===cell.col&&d.row===cell.row);if(d?.date)pin(d.date,'pointer');else closeTip()}
function stop(){++epoch;cancelAnimationFrame(raf);raf=0}
function animate(duration:number,step:(t:number)=>void,done=()=>{}){const id=epoch,start=performance.now();const tick=(time:number)=>{if(id!==epoch)return;const t=Math.min(1,(time-start)/duration);step(t);if(t<1)raf=requestAnimationFrame(tick);else{raf=0;done()}};raf=requestAnimationFrame(tick)}
function changeMode(value:string){if(mode.value===value)return;mode.value=value;clear();stop();if(reduced){drawMode.value=value;progress.value=1;fade.value=1;return}if(value==='skyline'){fade.value=1;animate(120,t=>fade.value=1-t,()=>{drawMode.value='skyline';fade.value=1;progress.value=0;animate(720,t=>{progress.value=t;void position()})})}else{animate(200,t=>progress.value=1-t*t,()=>{drawMode.value='grid';progress.value=1;fade.value=0;animate(120,t=>fade.value=t)})}}
// Cubic-bezier(.2,.7,.2,1), solved for x instead of approximating with a different curve.
function ease(x:number){let lo=0,hi=1;for(let i=0;i<12;i++){const t=(lo+hi)/2,xx=3*(1-t)*(1-t)*t*.2+3*(1-t)*t*t*.2+t*t*t;if(xx<x)lo=t;else hi=t}const t=(lo+hi)/2;return 3*(1-t)*(1-t)*t*.7+3*(1-t)*t*t+t*t*t}
const fraction=(p:SkylinePrism)=>progress.value>=1?1:mode.value==='grid'?progress.value:ease(Math.max(0,Math.min(1,(progress.value*720-Math.min(p.col*6,240))/480)))
const animated=(p:SkylinePrism)=>dataT.value>=1?p:{...p,h:p.h===null?null:(oldHeights.value[p.date]??0)+((p.h??0)-(oldHeights.value[p.date]??0))*dataT.value}
const faceCache=computed(()=>new Map(layout.value.prisms.map(p=>[p.date,prismAt(animated(p),fraction(p),pitch.value,layout.value)])))
const faces=(p:SkylinePrism)=>faceCache.value.get(p.date)!
const outline=(p:SkylinePrism)=>pointsAttr(silhouette(animated(p),fraction(p),pitch.value,layout.value))
function modeKey(e:KeyboardEvent){if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();changeMode(mode.value==='grid'?'skyline':'grid');nextTick(()=>root.value?.querySelector<HTMLButtonElement>('[aria-checked=true]')?.focus())}}
function reset(){dataset.value='Synthetic year';state.value='ready';mode.value='grid';drawMode.value='grid';selectedDate.value=null;tableOpen.value=false;clear();stop();progress.value=1;fade.value=1}
async function tableToggle(e:Event){tableOpen.value=(e.target as HTMLDetailsElement).open;await nextTick();tableOverflow.value=!!tableScroll.value&&tableScroll.value.scrollHeight>tableScroll.value.clientHeight}
watch([dataset,state],async([newData],[oldData])=>{clear();stop();dataT.value=1;if(!days.value.some(d=>d.date===selectedDate.value))selectedDate.value=days.value.at(-1)?.date??null;progress.value=1;fade.value=1;drawMode.value=mode.value;if(newData!==oldData&&state.value==='ready'&&drawMode.value==='skyline'&&!reduced){const before=layoutSkyline(sampleCells(oldData),Math.ceil(sampleCells(oldData).length/7),pitch.value);oldHeights.value=Object.fromEntries(before.prisms.map(p=>[p.date,p.h]));dataT.value=0;animate(240,t=>{dataT.value=t;void position()})}await nextTick();if(tableScroll.value)tableOverflow.value=tableScroll.value.scrollHeight>tableScroll.value.clientHeight})
function preference(){dataT.value=1;reduced=!!media?.matches;if(reduced){stop();drawMode.value=mode.value;progress.value=1;fade.value=1}}
onMounted(()=>{media=matchMedia('(prefers-reduced-motion: reduce)');preference();media.addEventListener('change',preference);observer=new ResizeObserver(()=>{pitch.value=pickPitch((board.value?.clientWidth??600)-24,weeks.value);moved()});if(board.value)observer.observe(board.value);document.addEventListener('pointerdown',pointerOutside);document.addEventListener('keydown',escape);window.addEventListener('scroll',moved,true);window.addEventListener('resize',moved)})
onBeforeUnmount(()=>{stop();cancelGrace();cancelAnimationFrame(positionRaf);observer?.disconnect();media?.removeEventListener('change',preference);document.removeEventListener('pointerdown',pointerOutside);document.removeEventListener('keydown',escape);window.removeEventListener('scroll',moved,true);window.removeEventListener('resize',moved)})
</script>
<template>
<section ref="root" class="skyusage-demo felix-skyline-demo" aria-label="Synthetic contribution skyline demonstration">
<p>Fictional contributions on consecutive calendar dates. No account data, network request or saved preference.</p>
<div class="skyusage-controls"><label>Dataset<select v-model="dataset"><option v-for="d in DATASETS" :key="d">{{ d }}</option></select></label><label>Data state<select v-model="state"><option value="ready">Ready</option><option value="loading">Loading</option><option value="empty">Empty</option><option value="error">Error</option></select></label><div v-if="state==='ready'" class="skyusage-mode" role="radiogroup" aria-label="View" @keydown="modeKey"><button v-for="v in ['grid','skyline']" :key="v" role="radio" :aria-checked="mode===v" :tabindex="mode===v?0:-1" @click="changeMode(v)">{{ v==='grid'?'Grid':'Skyline' }}</button></div><button @click="reset">Reset example</button></div>
<div ref="board" class="skyusage-board" @scroll="moved">
<template v-if="state==='ready'"><p v-if="layout.max===0">0 in the whole period.</p><span id="skyusage-hint" class="skyusage-sr">Arrow keys move by day or week. Home/End first/last. Page Up/Down four weeks. Enter or Space pins; Escape dismisses.</span>
<div v-if="drawMode==='skyline'" ref="scene" class="skyusage-scene" tabindex="0" role="group" aria-label="Synthetic contributions: Skyline view" :aria-describedby="'skyusage-hint'+(tip?' skyusage-tooltip':'')" @focus="focusScene" @blur="blurScene" @keydown="key"><svg :viewBox="`0 0 ${layout.width} ${layout.height}`" :width="layout.width" :height="layout.height" aria-hidden="true" @click="blankTap"><defs><pattern id="skyusage-hatch" width="5" height="5" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><rect width="5" height="5" fill="var(--sky-board)"/><path d="M0 0 V5" stroke="var(--sky-unknown)" stroke-width="2"/></pattern></defs><g v-for="p in layout.prisms" :key="p.date" class="skyusage-prism" :data-date="p.date" :data-kind="p.kind" :style="{'--sky-top':`var(--sky-top-${p.level??0})`}" @pointerenter="enter(p.date,$event)" @pointerleave="leave" @click.stop="pin(p.date,'pointer')"><polygon v-if="faces(p).left" class="skyusage-left" :points="pointsAttr(faces(p).left!)"/><polygon v-if="faces(p).front" class="skyusage-front" :points="pointsAttr(faces(p).front!)"/><polygon class="skyusage-top" :class="{'skyusage-unknown':p.kind==='unknown'}" :style="p.kind==='unknown'?{fill:'url(#skyusage-hatch)'}:{}" :points="pointsAttr(faces(p).top)"/></g><text v-for="m in monthMarkers" :key="m.col+'-'+m.label" class="skyusage-axis" :x="project(m.col+.5,7,0,pitch,layout)[0]" :y="project(m.col+.5,7,0,pitch,layout)[1]+.9*pitch" text-anchor="middle">{{ m.label }}</text><text v-for="r in [1,3,5]" :key="r" class="skyusage-axis" :x="project(0,r+.5,0,pitch,layout)[0]-.4*pitch" :y="project(0,r+.5,0,pitch,layout)[1]" text-anchor="end">{{ ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][r] }}</text><polygon v-if="hoverDate&&layout.prisms.find(p=>p.date===hoverDate)" class="skyusage-overlay" :points="outline(layout.prisms.find(p=>p.date===hoverDate)!)"/><template v-if="focusVisible&&selected"><polygon class="skyusage-overlay skyusage-halo" :points="outline(selected)"/><polygon class="skyusage-overlay skyusage-focus" :points="outline(selected)"/></template></svg></div>
<div v-else class="skyusage-grid" role="group" aria-label="Synthetic contributions: Grid view" :style="{opacity:fade}"><template v-for="c in cells" :key="`${c.col}-${c.row}`"><button v-if="c.date" class="skyusage-cell" :class="{'skyusage-unknown':c.count===null}" :style="{'--sky-top':`var(--sky-top-${c.level??0})`}" :data-date="c.date" :tabindex="(selectedDate??days.at(-1)?.date)===c.date?0:-1" :aria-label="text(c.date)" :aria-describedby="tip?.date===c.date?'skyusage-tooltip':undefined" @focus="selectedDate=c.date;focused=true;if(!suppressed)show(c.date,'focus',true)" @blur="blurScene" @keydown="key" @pointerenter="enter(c.date,$event)" @pointerleave="leave" @click="pin(c.date,'pointer')"></button><span v-else aria-hidden="true"></span></template></div>
</template><p v-else :role="state==='error'?'alert':'status'">{{ state==='loading'?'Loading demonstration; data withheld.':state==='empty'?'No days in this period.':'Could not load demonstration data. Use Reset example.' }}</p>
</div>
<template v-if="state==='ready'"><div class="skyusage-legend" aria-label="Contribution levels"><span>Less</span><i v-for="n in 5" :key="n" class="skyusage-swatch" :style="{'--sky-top':`var(--sky-top-${n-1})`}" aria-hidden="true"></i><span>More</span><span v-if="days.some(c=>c.count===null)">Hatched: no data</span></div><p class="skyusage-note">Height = count (linear, max {{ layout.max }}). Positive days have a minimum visible height; exact counts remain in the tooltip and table.</p><details :open="tableOpen" @toggle="tableToggle"><summary>View data as table</summary><div ref="tableScroll" class="skyusage-table-scroll" :tabindex="tableOverflow?0:undefined" :role="tableOverflow?'region':undefined" :aria-label="tableOverflow?'Scrollable synthetic contributions table':undefined"><table class="skyusage-table"><caption>{{ days[0]?.date }} to {{ days.at(-1)?.date }}: synthetic contributions</caption><thead><tr><th scope="col">Date</th><th scope="col">Contributions</th></tr></thead><tbody v-if="tableOpen"><tr v-for="d in days" :key="d.date!"><th scope="row">{{ d.date }}</th><td>{{ d.count===null?'no data':d.count }}</td></tr></tbody></table></div></details></template>
<div v-if="tip" id="skyusage-tooltip" ref="tooltip" role="tooltip" class="skyusage-tooltip" :style="tipStyle" @pointerenter="overTip=true;cancelGrace()" @pointerleave="overTip=false;leave()">{{ text(tip.date) }}</div><span class="skyusage-sr" aria-live="polite">{{ live }}</span>
</section>
</template>

<style scoped>
/* Felix-only native control accent. */
:is(input[type=range],input[type=checkbox],input[type=radio]){accent-color:var(--vp-c-brand-1)}

.skyusage-demo{--sky-top-0:var(--vp-c-divider);--sky-top-1:#99f6e4;--sky-top-2:#2dd4bf;--sky-top-3:#0f766e;--sky-top-4:#134e4a;--sky-edge:var(--vp-c-text-1);--sky-focus:var(--vp-c-text-1);--sky-hover:var(--vp-c-text-1);--sky-halo:var(--vp-c-bg);--sky-unknown:var(--vp-c-text-2);--sky-label:var(--vp-c-text-2);--sky-control:var(--vp-c-bg);--sky-text:var(--vp-c-text-1);color:var(--vp-c-text-1);background:var(--vp-c-bg)}
:global(html.felix-dark .felix-skyline-demo){--sky-top-1:#134e4a;--sky-top-2:#0f766e;--sky-top-3:#2dd4bf;--sky-top-4:#99f6e4}
</style>
